window.docContents[48].resolve({"/rules/PL1005/#PL1005-proof-shape":{"contents":"The replacement proves the same proposition. Classical, erased proofs are permitted when the surface claims Standard-Logical; executable behavior is a separate account (PL1007, PL3001, PL3002).\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL1005: Transitive axioms must fit the selected profile","header":"Required proof shape","id":"/rules/PL1005/#PL1005-proof-shape"},"/rules/PL2004/#PL2004-proof-shape":{"contents":"No proof obligation: the rule concerns the declaration inventory. The removed import must not have supplied evidence the claim still relies on.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL2004: Owned coverage must match the exact Lake inventory","header":"Required proof shape","id":"/rules/PL2004/#PL2004-proof-shape"},"/rules/PL4002/#PL4002-proof-shape":{"contents":"The fence proves exactly the claim the surrounding prose states. A narrower foundation or an execution claim in the prose needs its own evidence; fence success establishes only Standard-Logical admission.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL4002: Positive examples require warning-free elaboration and admission","header":"Required proof shape","id":"/rules/PL4002/#PL4002-proof-shape"},"/rules/PL5001/#PL5001-proof-shape":{"contents":"No proof obligation: the rule checks presence of documentation.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL5001: Claimed modules require module documentation","header":"Required proof shape","id":"/rules/PL5001/#PL5001-proof-shape"}});